css:
body{
    margin:0;
    padding:0;
}
.top{
    height:140px;
    background-color:#002e63;
    color:white;
    padding:15px;
    gap:50px;
}
.me{
    position:absolute;
    top:80px;
    left:330px;
}
.me h1{
    font-size:1cm;
}
img{
    border-radius: 60px;
    height:110px;
    width:110px;
    position:relative;
    left:50px;
}
.whole{
    display: grid;
    grid-template-columns: 1fr 2fr;
    gap:10px;
}
.left{
    background-color:#dcdcdc;
}
.left, .right{
    color:#002e63;
    padding:5px;
}
